import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Linter","description":"","frontmatter":{"title":"Linter","type":"adr","date":"2026-08-24T00:00:00.000Z","status":"proposed","status_note":"Accepted — `handl lint` is an extensible rule registry with auto-fix."},"headers":[],"relativePath":"handl/project/adrs/0015-linter.md","filePath":"vendored/handl/project/adrs/0015-linter.md"}'),a={name:`handl/project/adrs/0015-linter.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0015-linter" tabindex="-1">ADR-0015: Linter <a class="header-anchor" href="#adr-0015-linter" aria-label="Permalink to “ADR-0015: Linter”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>handl lint</code> checks documents against an extensible rule set</strong>; paths may be files or globs, and <code>--fix</code> applies auto-fixes.</li><li><strong>A rule is a pure function</strong> from the parsed document + file metadata to <code>LintIssue[]</code> (rule, severity, file, line, message, optional fix).</li><li><strong>Severity is <code>error</code> / <code>warn</code> / <code>info</code></strong>; exit 0 unless an <code>error</code> is present, and <code>--fail-on-warn</code> escalates warnings.</li><li><strong>The initial rule set</strong> is naming-convention, missing-annotations, deprecated-keyword, unused-field, style (auto-fixable via the formatter) and missing-version.</li><li><strong>Rules are namespaced and extensible</strong> — hosts register their own (<code>peregrin.event-contract</code>), and <code>--except</code> disables one by name.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The linter had a fixed rule list, so every new convention meant editing the linter and host-specific policy had no home. A registry of pure rules keeps the linter generic and lets hosts extend it without forking.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A fixed rule list</strong> — hooks and hosts need their own rules.</li><li><strong>Fixing in rule order</strong> — <code>--fix</code> applies in a stable order across all rules.</li><li><strong>Warnings failing by default</strong> — only errors gate; <code>--fail-on-warn</code> opts in.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Rules are data/functions, registered; the linter is a driver.</li><li>Auto-fix reuses the formatter for style.</li><li>Namespacing prevents host/language collisions.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/plugin-ext-lint/</code> — registry and the initial rules.</li><li><code>plugin-engine-lint</code> — the generic driver.</li><li>Rule tests and CLI tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Command surface, severities, issue shape, the initial rules and plugin model: +<a href="./../design/0015-linter.html"><code>design/0015-linter.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};